globalThis.KENGURU_GRADE_CONDITIONS = {"2016":{"1":{"question":"Карточку, изображённую справа, перевернули сначала через левый край, а потом — через нижний край. Что получилось?","choices":["Кенгуру лежит головой влево, хвост справа","Кенгуру лежит головой вправо, хвост слева","Кенгуру лежит головой вправо, хвост загибается вниз слева","Кенгуру сидит и смотрит вправо","Кенгуру перевёрнут вверх ногами"],"image":"assets/grade-conditions/2016/task-01.webp","imageWidth":218,"imageHeight":228,"choiceImages":["assets/grade-conditions/2016/choice-01-1.webp","assets/grade-conditions/2016/choice-01-2.webp","assets/grade-conditions/2016/choice-01-3.webp","assets/grade-conditions/2016/choice-01-4.webp","assets/grade-conditions/2016/choice-01-5.webp"]},"2":{"question":"Вася зашифровал цифры буквами так, что 27108 = КЕНГА. Какое из «чисел» А–Д наименьшее?","choices":["КГАНЕ","КАГЕН","АЕКНГ","НАКЕГ","АГЕНК"]},"3":{"question":"С помощью 8 круглых магнитов Лиза прикрепила 7 открыток на холодильник (см. рисунок). Какое наибольшее количество магнитов можно убрать так, чтобы не упала ни одна открытка?","choices":["3","4","5","6","7"],"image":"assets/grade-conditions/2016/task-03.webp","imageWidth":263,"imageHeight":184},"4":{"question":"Чему равна сумма второго и третьего двузначных чисел?","choices":["четырнадцатому двузначному числу","шестому двузначному числу","пятому двузначному числу","трехзначному числу","двадцать третьему двузначному числу"]},"5":{"question":"Сколько раз придется поменять местами вилку и нож, чтобы около каждой тарелки, как и полагается, справа лежал нож, а слева — вилка?","choices":["0","1","2","3","5"],"image":"assets/grade-conditions/2016/task-05.webp","imageWidth":550,"imageHeight":115},"6":{"question":"Жан-Кристоф продолжает изучать русский язык. Он ищет числа, словесная запись которых состоит ровно из трех слов: ШЕСТЬ, ШЕСТЬДЕСЯТ, ТЫСЯЧ. Например, таково число 6060 — ШЕСТЬ ТЫСЯЧ ШЕСТЬДЕСЯТ. Сколько всего таких чисел?","choices":["3","4","5","6","7"]},"7":{"question":"Треть удвоенной половины равна","image":"assets/grade-conditions/2016/task-07.webp","imageWidth":859,"imageHeight":68},"8":{"question":"Из заготовки (см. рисунок) сложили коробку без крышки. Какая буква оказалась на дне?","choices":["К","Е","Н","Г","А"],"image":"assets/grade-conditions/2016/task-08.svg","imageWidth":220,"imageHeight":115},"9":{"question":"Пятьсот пятьдесят пять девяток сложили, а сумму разбили на пятерки. Сколько получилось пятерок?","choices":["45","111","555","900","999"]},"10":{"question":"Клара хочет выложить большой треугольник, используя одинаковые треугольные карточки. Она уже положила 5 карточек (см. рисунок). Какое наименьшее количество карточек ей придется добавить?","choices":["1","2","3","4","5"],"image":"assets/grade-conditions/2016/task-10.svg","imageWidth":220,"imageHeight":158},"11":{"question":"Какая из картинок А–Д не может быть получена наложением двух одинаковых квадратных карточек?","image":"assets/grade-conditions/2016/task-11.webp","imageWidth":920,"imageHeight":137},"12":{"question":"У Димы часы отстают на 10 минут, а он думает, что они спешат на 5 минут. Посмотрев на свои часы, Дима решил, что сейчас полдень. Который сейчас час на самом деле?","choices":["11: 45","11: 55","12: 00","12: 05","12:15"]},"13":{"question":"Белки А, Б, В, Г и Д собирают орехи, помеченные на рисунке звездочками. Белки начинают одновременно и бегут с одинаковыми скоростями, каждая — к ближайшему ореху. Схватив орех, белка бежит к новому ближайшему ореху. Какой белке достанется два ореха?","choices":["А","Б","В","Г","Д"],"image":"assets/grade-conditions/2016/task-13.webp","imageWidth":780,"imageHeight":59},"14":{"question":"В классе 30 учеников. Они сели за парты по двое так, что каждый мальчик сидит с девочкой, и ровно половина девочек сидит с мальчиками. Сколько в классе мальчиков?","choices":["25","20","15","10","5"]},"15":{"question":"Когда из листа бумаги вырезали прямоугольник ABCD (см. рисунок), периметр листа увеличился на 6, а площадь листа уменьшилась на 6. Чему равна длина отрезка AB?","image":"assets/grade-conditions/2016/task-15.webp","imageWidth":980,"imageHeight":202},"16":{"question":"В детском садике работают три воспитательницы: Марина, Аня и Наташа. Каждый день с понедельника по пятницу работают ровно две из них. Марина работает три дня, а Аня — четыре. Сколько дней работает Наташа?","choices":["1","2","3","4","5"]},"17":{"question":"У тройняшек Джима, Джона и Джека есть брат Джордж, который младше их ровно на 3 года. В их день рождения число свечек на праздничном торте было равно сумме возрастов всех четырех братьев. Сколько свечек могло оказаться на этом торте?","choices":["51","53","54","56","59"]},"18":{"question":"На прямой расположено четыре точки A, B, C и D. Известно, что AB = 1, BC = 2, CD = 3, DA = 4. Какие две точки крайние?","choices":["A и D","A и C","B и C","B и D","невозможно определить"]},"19":{"question":"Напротив зеркала на стене висят часы. Сейчас их отражение выглядит так, как показано на рисунке справа. А как оно выглядело 10 минут назад?","image":"assets/grade-conditions/2016/task-19.webp","imageWidth":971,"imageHeight":220},"20":{"question":"На столе стояла ваза с вишнями. Сначала Женя съела пятую часть всех вишен, а потом Федя — седьмую часть всех оставшихся вишен. Сколько вишен могло остаться в вазе?","choices":["20","24","28","30","35"]},"21":{"question":"Куб 2 × 2 × 2 построен из 8 одинаковых кубиков, некоторые из которых темные, а остальные — белые. Четыре грани куба выглядят так, как на рисунке 1, а одна — так, как на рисунке 2. Как выглядит шестая грань?","image":"assets/grade-conditions/2016/task-21.webp","imageWidth":977,"imageHeight":201},"22":{"question":"Полоску бумаги, изображенную на рисунке, разрезали на три части так, что сумма получившихся трех чисел оказалась наименьшей из возможных. Какое из чисел А–Д является одним из слагаемых этой суммы?","choices":["195","376","819","1953","2581"],"image":"assets/grade-conditions/2016/task-22.webp","imageWidth":337,"imageHeight":72},"23":{"question":"В поезде 5 вагонов, в каждом вагоне едет хотя бы один пассажир. Будем говорить, что два пассажира едут рядом, если они едут в одном вагоне или в двух соседних. Известно, что рядом с каждым пассажиром едет еще либо 3, либо 7 пассажиров. Сколько всего пассажиров в поезде?","choices":["9","10","12","15","невозможно определить"]},"24":{"question":"Каждая буква слова КЕНГУРУ заменена одной из цифр 1, 2, 3, 4, 5, 6. Различные буквы заменены различными цифрами. Получившееся число делится на 3, но не делится на 2. На какую цифру заменена буква У?","choices":["1","3","4","5","6"]},"25":{"question":"У квадратного листа бумаги 10 ×10 сначала загнули справа полоску шириной 1, потом сверху полоску высотой 1, потом снова справа, потом снова сверху, и так далее (см. рисунок), пока не получился квадрат 6 × 6. После этого правый верхний квадратик 1×1 проткнули шилом. Сколько получится дырок, если развернуть этот лист?","choices":["5","9","16","25","36"],"image":"assets/grade-conditions/2016/task-25.webp","imageWidth":328,"imageHeight":148},"26":{"question":"По круговой дорожке в одном направлении движутся Соня на ходулях и малыш Федя на велосипеде. Скорость Феди в пять раз больше скорости Сони, и поэтому он время от времени ее обгоняет. В скольких разных точках дорожки будут происходить обгоны?","choices":["3","4","5","6","7"]},"27":{"question":"Натуральное число A таково, что НОК (100, A) = 600, а НОК (100, A + 1) = 100. Чему равно НОК (100, A + 2)?","choices":["100","900","1300","2100","невозможно определить"]},"28":{"question":"По кругу сидят 2016 человек, каждый из которых либо рыцарь, который всегда говорит правду, либо лжец, который всегда лжет. Каждый человек сказал обо всех, кроме себя и своих соседей: «Все они — лжецы». Сколько рыцарей за этим столом?","choices":["0","1","2","3","1008"]},"29":{"question":"В каждый из семи кружочков (см. рисунок) Алиса хочет вписать одно из чисел 0, 1 или 2 так, чтобы сумма чисел в вершинах каждого белого треугольника делилась на три, а сумма чисел в вершинах каждого закрашенного треугольника не делилась на три. Два числа она уже вписала. Какое число Алиса впишет вместо вопросительного знака?","choices":["0","1","2","1 или 2","такая расстановка невозможна"],"image":"assets/grade-conditions/2016/task-29.webp","imageWidth":305,"imageHeight":122},"30":{"question":"В клетки таблицы 3 × 3 вписаны 9 различных натуральных чисел, сумма которых равна 50. Катя нашла сумму чисел в каждом из квадратов 2 × 2. Какова наименьшая возможная сумма этих четырех сумм?","choices":["65","67","69","82","95"]}}};
globalThis.KENGURU_GRADE_SOLUTION_STEPS = {};
globalThis.KENGURU_GRADE_KEYS = {"2016":[["Контур кенгуру внутри квадрата. Его голова направлена вниз, лапы и хвост — к верхнему краю.","Д","assets/grade-key-figures/2016-01.svg",104,105],["НАКЕГ","Г"],["4","Б"],["четырнадцатому двузначному числу","А"],["2 раза","В"],["3 числа","А"],["1/3","Г"],["Е","Б"],["999","Д"],["4 карточки","Г"],["Серая фигура в форме домика. Прямоугольник внизу, над ним треугольная крыша вершиной вверх.","Д","assets/grade-key-figures/2016-11.svg",84,98],["12:15","Д"],["В","В"],["10 мальчиков","Г"],["2","В"],["3 дня","В"],["53","Б"],["B и D","Г"],["Круглый циферблат с двенадцатью точками без цифр. Длинная стрелка направлена примерно к 11, короткая примерно к 2.","А","assets/grade-key-figures/2016-19.svg",120,120],["24","Б"],["Квадрат, разбитый на сетку 2 на 2.","А","assets/grade-key-figures/2016-21.svg",66,66],["1953","Г"],["12 пассажиров","В"],["3","Б"],["25","Г"],["4","Б"],["1300","В"],["2","В"],["0","А"],["67","Б"]]};
globalThis.KENGURU_GRADE_TITLES = {"2016":["Карточка с кенгуру","Буквенный шифр Васи","Открытки на магнитах","Сумма двух двузначных чисел","Вилки и ножи","Числа из трёх слов","Треть удвоенной половины","Буква на дне коробки","Девятки и пятёрки","Треугольник из карточек","Два квадрата внахлёст","Ошибка на часах Димы","Белки за орехами","Мальчики и девочки за партами","Вырезанный прямоугольник","Рабочие дни воспитательниц","Свечки на торте тройняшек","Крайние точки на прямой","Часы в зеркале","Вишни в вазе","Шестая грань куба","Полоска с цифрами","Пассажиры в соседних вагонах","Цифра для буквы У","Дырочки в сложенном листе","Ходули и велосипед","НОК с числом 100","Рыцари и лжецы за столом","Числа в цветных треугольниках","Суммы в квадратах таблицы"]};
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const officialSolutions = globalThis.KENGURU_GRADE_SOLUTION_STEPS ?? {};
  const nativeConditions = globalThis.KENGURU_GRADE_CONDITIONS ?? {};
  const nativeKeys = globalThis.KENGURU_GRADE_KEYS ?? {};
  const visualLessons = globalThis.KenguruVisualLessons ?? {};
  const editorialTitles = globalThis.KENGURU_GRADE_TITLES ?? {};

  function conditionScene(path, width, height, label) {
    return visual.svg(`<image href="${visual.escape(path)}" width="${width}" height="${height}"/>`,
      label, `0 0 ${width} ${height}`, 'legacy-scene').replace('<svg ', `<svg style="max-width:${width}px" `);
  }

  function answerDiagram(path, sourceWidth, sourceHeight) {
    const scale = Math.min(420 / sourceWidth, 300 / sourceHeight);
    const width = sourceWidth * scale;
    const height = sourceHeight * scale;
    const x = (420 - width) / 2;
    const drawing = visual.svg(`<image href="${visual.escape(path)}" x="${x}" y="8" width="${width}" height="${height}"/>`,
      'Рисунок к официальному ответу', `0 0 420 ${height + 16}`, 'worked-scene');
    return path.endsWith('.svg') ? drawing
      : drawing.replace('<svg ', `<svg style="max-width:${840 / scale}px;margin-inline:auto" `);
  }

  function officialSteps(stages) {
    return stages.map(({text, title}, index) => [
      index === stages.length - 1 ? 'Ответ' : `Шаг ${index + 1}`,
      title ?? (index === 0 ? 'Начинаем решение' : index === stages.length - 1 ? 'Проверяем ответ' : 'Продолжаем решение'),
      text,
    ]);
  }

  function createEdition(edition) {
    const {year, id, grades, label, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const answerLetters = [...(year < 2008 ? 'ABCDE' : 'АБВГД')];
    const groupSize = cards.length / 3;
    const lessons = [];
    const scenes = [];

    for (const [index, [width, height, letterKey]] of cards.entries()) {
      const number = index + 1;
      const padded = String(number).padStart(2, '0');
      const folder = `assets/grades-5-6/${year}`;
      const originalImage = `${folder}/task-${padded}.webp`;
      const description = `Условие задачи №${number}. Кенгуру ${year}, 5–6 классы.`;
      const custom = visualLessons[year]?.[number];
      const native = nativeConditions[year]?.[number];
      const official = officialSolutions[year]?.[number]?.steps;
      const question = custom?.question ?? native?.question ?? '';
      const choices = custom?.choices ?? native?.choices ?? ['', '', '', '', ''];
      const paperEdition = !custom && !official?.length;
      const intro = ['Условие', 'Условие задачи', 'Выбери ответ и нажми «Далее».'];
      const officialKey = nativeKeys[year]?.[index];
      const [answerText, answerLetter, answerImage, answerWidth, answerHeight] = officialKey ?? [];
      const answer = officialKey && answerLetter ? answerLetters.indexOf(answerLetter) : letterKey;
      const answerStep = officialKey
        ? ['Ответ', 'Официальный ответ', answerLetter ? `Вариант ${answerLetter}. ${answerText}` : answerText]
        : ['Ответ', 'Проверяем ответ', 'Сравни свой выбор с официальным ответом.'];
      const steps = custom?.steps ?? [intro, ...(official?.length ? officialSteps(official) : [answerStep])];
      const figure = native?.image;
      const title = custom?.title ?? editorialTitles[year]?.[index] ?? `Задача ${number}`;

      lessons.push({
        number,
        title,
        short: custom?.short ?? title,
        skill: custom?.skill ?? '',
        answer,
        choices,
        choiceImages: custom ? custom.choiceImages : native?.choiceImages,
        question,
        conditionImage: custom?.conditionImage ?? (!custom ? figure : undefined),
        conditionAlt: !custom ? native?.figureAlt : undefined,
        legacyOriginal: !custom || Boolean(custom.originalAtStart),
        hideIntroText: !custom,
        paperEdition,
        showCompletedStep: !paperEdition,
        officialValueKey: Boolean(officialKey),
        points: 3 + Math.floor(index / groupSize),
        originalImage,
        steps,
      });

      const initialScene = !question || custom?.originalAtStart
        ? conditionScene(originalImage, width, height, description)
        : figure && !custom ? conditionScene(figure, native.imageWidth, native.imageHeight, native.figureAlt ?? description) : '';
      const key = officialKey
        ? (answerImage ? answerDiagram(answerImage, answerWidth, answerHeight) : '')
        : visual.answerScene({letter: answerLetters[answer], value: choices[answer]});
      scenes.push((step, frame) => {
        if (custom && !(step === 0 && custom.originalAtStart)) return custom.scene(step, frame);
        if (step === 0) return initialScene;
        if (paperEdition) return key;
        // An empty stage is appropriate when this part of the proof has only a verbal argument.
        return visual.workedScene(official[step - 1], frame) || (step === steps.length - 1 ? key : '');
      });
    }

    return {year, id, grades, label, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes, paperEdition: true};
  }

  for (const edition of globalThis.KENGURU_GRADES_5_6 ?? []) {
    archive[edition.id] = createEdition(edition);
  }
})();

